'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($filters['age_group']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div><div><label class="form-label" for="registration">Registration status</label><select class="form-control" id="registration" name="registration_status"><option value="">All</option><?php foreach(['verified','pending','rejected'] as $s): ?><option value="<?= $s ?>" <?= ($filters['registration_status']??'')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div><div class="flex items-end gap-2"><button class="btn-primary flex-1" type="submit">Filter</button><a class="btn-muted" href="<?= site_url('children') ?>">Reset</a></div></form>
